import logging
import time

import serial

from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class SerialControl(object):
    """Class to manage serial COM connection"""

    def __init__(self, com_id):
        """
        Basic initialization.
        :param com_id:
        """
        self.serial_com = com_id
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UECONTROL'})
        self.ser = None
        self.last_history = []

    def flush_last_com_history(self):
        """
        Resets own last_history
        :return: last_history
        """
        result = self.last_history
        self.last_history = []
        return result

    def connect_to_com(self, tries=3, b=115200):
        """Establish COM connection"""
        if self.ser:
            self.disconnect_com()
        self.ser = serial.Serial(port='COM' + self.serial_com, baudrate=b, stopbits=serial.STOPBITS_ONE,
                                 parity=serial.PARITY_NONE, timeout=2, xonxoff=1)

    def disconnect_com(self):
        """Disconnect from COM"""
        self.ser.close()
        self.ser = None

    def _wait_for_response(self, wait_for_multiresponse, wait_for_ok=True, timeout=4):
        output = []
        self.logger.info('_wait_for_response called with timeout value={}'.format(timeout))
        end_time = time.time() + float(timeout)
        while time.time() <= end_time:
            time.sleep(0.1)
            self.logger.info('_wait_for_response while loop beginning')
            current_response = self.read_com_command()
            if not current_response:
                continue
            output += current_response
            if self._is_response_error(output):
                raise serial.SerialException("Response: '{}'".format(output))
            if self._is_response_relevant(output) and wait_for_ok and self._is_response_ok(output):
                if wait_for_multiresponse:
                    continue
                return output
            self.logger.info('_wait_for_response got no relevant output, next iteration begins')
        return self._verify_and_return_output(output)

    def _verify_and_return_output(self, output):
        if self._is_response_relevant(output):
            return output
        raise serial.SerialException("Timeout reached, got no response: {}".format(output))

    def _is_response_relevant(self, output):
        return (output is not None) and (len(output) > 0) and any("AT+" not in line for line in output)

    def _is_response_ok(self, output):
        return "OK" in output

    def _is_response_error(self, output):
        for line in output:
            if "ERROR" in line:
                return True
        return False

    def _is_timeout(self, end_time):
        return time.time() > end_time

    def _send_and_verify(self, cmd, wait_for_multiresponse, wait_for_ok=True, timeout=4):
        self.logger.info("Sending AT command '{}' with timeout value={}".format(cmd, timeout))
        try:
            self.send_com_command(cmd)
            return self._wait_for_response(wait_for_multiresponse, wait_for_ok, timeout=timeout)
        except serial.SerialException as e:
            err_msg = "AT command failed: '{}' {}. Timeout was: {}".format(cmd, e.args[0], timeout)
            self.logger.error(err_msg)
            raise serial.SerialException(err_msg)

    def send_and_verify(self, cmd, tries=1, timeout=4, wait_for_multiresponse=None, wait_for_ok=True):
        """
        Sends command to serial port and verifies if output have succeeded.
        :param cmd: Command to be sent.
        :param tries: How many times to try to get appropriate result.
        :param timeout: Time to wait for output.
        :return: (list) Lines of serial output.
        :raises: :py:class:`serial.SerialException`: If response verification fails.
        """
        for trial in range(tries):
            try:
                return self._send_and_verify(cmd, wait_for_multiresponse, wait_for_ok, timeout=timeout)
            except serial.SerialException:
                if trial + 1 >= tries:
                    raise

    def send_com_command(self, cmd):
        """Send a command to com"""
        self.logger.debug('sending ' + str(cmd))
        self.last_history.append("Send: " + cmd)
        self.ser.write((cmd + '\r\n').encode("utf-8", errors='ignore'))
        self.ser.flush()

    def read_com_command(self):
        """Read COM output"""
        lines = [x.decode("utf-8", errors='ignore') for x in self.ser.readlines()]
        self.last_history += ["Read: " + x.rstrip('\r\n') for x in lines]
        output_rstripped = [x.rstrip('\r\n') for x in lines]
        self.logger.debug('Reading serial output = {}'.format(output_rstripped))
        return output_rstripped

    def check_output_if_ok(self, cmd_list):
        """Verify serial output"""
        try:
            if not cmd_list:
                raise Exception("Output from COM empty!")
            return bool(cmd_list[-1] == "OK")
        except IndexError as e:
            self.logger.error(str(e))
            return False

    def check_if_is_in_operational_state(self, cmd_to_send, tries=5, timeout=5):
        """Send a command to COM and check if response is correct"""
        allowed_status = ['CFUN: 1', 'CFUN: 0', 'CFUN:1', 'CFUN:0']
        self.logger.debug('Start checking if UE is in operational state')
        for _ in range(tries):
            output_lines = self.send_and_verify(cmd_to_send, tries, timeout)
            for line in output_lines:
                if any(search for search in allowed_status if search in line):
                    return
        raise Exception("Ue not in operational state!")

    def wait_for_com_open(self, timeout=5):
        """Wait for timeout for open com port"""
        self.logger.debug('_wait_for_com_open called with timeout value={}'.format(timeout))
        end_time = time.time() + float(timeout)
        while time.time() <= end_time:
            time.sleep(0.1)
            self.logger.debug('_wait_for_com_open while loop beginning')
            if not self.check_serial_com_open():
                continue
            else:
                return
        raise Exception('Serial is still not open during {} timeout.'.format(timeout))

    def check_serial_com_open(self):
        """Check serial port COM is open"""
        self.ser.isOpen()
